const rawQuery = $fromAI("query", "Número do pedido citado pelo cliente");
const orderId = String(rawQuery).replace(/\D/g, "") || "0000";

const mockDatabase = {
  "9988": {
    pedido_id: "9988",
    restaurante: "Burger Lab Gourmet",
    valor_total: 84.90,
    tempo_atraso_min: 125,
    status_gps_entregador: "Parado há 40 min a 2.3km do destino",
    cliente_vip: true,
    risco_fraude: "Baixo (0 reembolsos nos últimos 90 dias)",
    sla_estourado: true
  },
  "1020": {
    pedido_id: "1020",
    restaurante: "Sushi Express Paulista",
    valor_total: 210.00,
    tempo_atraso_min: 15,
    status_gps_entregador: "Em rota - 400m do cliente",
    cliente_vip: false,
    risco_fraude: "Alto (4 reembolsos solicitados na última semana)",
    sla_estourado: false
  }
};

const resultado = mockDatabase[orderId] || {
  pedido_id: orderId,
  restaurante: "Parceiro iFood #" + orderId.slice(0, 2),
  valor_total: 62.50,
  tempo_atraso_min: 55,
  status_gps_entregador: "Rota em atraso moderado",
  cliente_vip: true,
  risco_fraude: "Baixo",
  sla_estourado: true
};

return JSON.stringify(resultado);

const rawOutput = $input.first().json.output || "{}";
const cleanJsonString = rawOutput.replace(/```json\n?|```/g, "").trim();

let parsedData;
try {
  parsedData = JSON.parse(cleanJsonString);
} catch (e) {
  parsedData = { erro_parse: rawOutput };
}

return [
  {
    json: {
      protocolo: "IFD-" + Math.floor(100000 + Math.random() * 900000),
      timestamp: new Date().toLocaleTimeString("pt-BR"),
      ...parsedData
    }
  }
];
